const picker=document.querySelector('.playlist-picker');playlists.forEach((id,index)=>{const button=el('button',index===2?'Jotne Thasha Valobasha':'Playlist '+(index+1));button.type='button';button.classList.toggle('active',index===0);button.setAttribute('aria-pressed',String(index===0));button.addEventListener('click',()=>{picker.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});const frame=document.getElementById('aarong-playlist-player');frame.src='https://www.youtube-nocookie.com/embed/videoseries?list='+id;frame.title=index===2?'Jotne Thasha Valobasha campaign playlist':'Aarong Dairy campaign playlist '+(index+1);document.getElementById('playlist-external').href='https://youtube.com/playlist?list='+id;document.getElementById('playlist-status').textContent='Campaign playlist '+(index+1)+' selected'});picker.append(button)});
